const NORM = (s) => String(s || "").trim().toLowerCase();
const BY_NAME = new Map(Object.keys(CATALOG).map((k) => [NORM(k), k]));
/* Liefert { images: [start, ende] | null, p, s, setup, move, tips } oder null */
export function catalogFor(name) {
  const key = BY_NAME.get(NORM(name));
  if (!key) return null;
  const [dsId, arch] = CATALOG[key];
  const a = ARCH[arch];
  if (!a) return null;
  return { images: dsId ? [`/ex/${dsId}/0.webp`, `/ex/${dsId}/1.webp`] : null, ...a };
}
